#!/bin/bash
# =============================================================================
# 02_benchmark_pseudobulk.sh
# Benchmark 1 (Methods): deconvolute pseudo-bulk mixtures with KNOWN cell proportions.
# For each of the 16 cell types, a pseudo-bulk CPM matrix was generated by bootstrap
# resampling that cell type into the reference at varying fractions (columns = mixtures).
# Each matrix is deconvoluted in CIBERSORTx Fractions mode (no batch correction) and the
# recovered fraction of the spiked cell type is compared with the ground truth.
#
# The same script, pointed at pseudo-bulks built from EXTERNAL cHL scRNA-seq references
# (10X / Aoki / Stewart), assesses generalisation of the signature matrix.
#
# Usage:  bash 02_benchmark_pseudobulk.sh
# =============================================================================

CIBERSORT_ROOT="${CIBERSORT_ROOT:-/oak/stanford/groups/emoding/analysis/brian/Cibersort}"
INPUT_DIR="${INPUT_DIR:-$CIBERSORT_ROOT/bulk_input}"
FRACTIONS_SIF="${FRACTIONS_SIF:-$CIBERSORT_ROOT/fractions.sif}"
PARTITION="${SLURM_PARTITION:-emoding}"
sigmatrix="/src/data/cHL_signature_matrix_400_800.txt"

: "${CIBERSORTX_USER:?}"; : "${CIBERSORTX_TOKEN:?}"

celltypes=(B_GC B_Memory B_preGC DC_Conventional DC_Plasmacytoid HRS ILC Macrophage NK Plasma T_CD4 T_CD8 T_gd T_Treg CAF T_MKI67)

for ct in "${celltypes[@]}"; do
  mixture="/src/data/pseudobulk_cHL_${ct}_cpm.txt"          # genes x mixtures, CPM
  outdir="$CIBERSORT_ROOT/cHL_sigmtx_400_800_${ct}_pseudo/"
  sbatch <<EOF
#!/bin/bash
#SBATCH --job-name=Ciber_pseudo_${ct}
#SBATCH --time=0-00:30:00
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=4
#SBATCH --mem-per-cpu=4G
#SBATCH --partition=${PARTITION}

mkdir -p ${outdir}
singularity exec -c -B ${INPUT_DIR}:/src/data -B ${outdir}:/src/outdir \\
  ${FRACTIONS_SIF} /src/CIBERSORTxFractions \\
  --username ${CIBERSORTX_USER} --token ${CIBERSORTX_TOKEN} \\
  --sigmatrix ${sigmatrix} \\
  --mixture ${mixture} \\
  --verbose TRUE
EOF
done
